-- ---------------------------------------------------------------------------
-- 0028_kristal_catering — UP
-- Специфікація: specs/028-catering/spec.md
--
-- 1) Таблиця сторінок напрямку «Ми можемо для Вас приготувати» (4 формати).
-- 2) Таблиця готових комплексів меню для кожної сторінки.
-- 3) Стартовий контент без жорстких цін («Розрахунок за запитом»).
-- 4) SEO URLs, подія меню адмінки, реєстрація модуля та базові налаштування.
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS `{{PREFIX}}kristal_catering_page` (
  `page_id`          INT(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `code`             VARCHAR(32)      NOT NULL,
  `slug`             VARCHAR(64)      NOT NULL,
  `title`            VARCHAR(160)     NOT NULL,
  `short_desc`       VARCHAR(280)     NOT NULL DEFAULT '',
  `hero_label`       VARCHAR(120)     NOT NULL DEFAULT '',
  `hero_title`       VARCHAR(160)     NOT NULL DEFAULT '',
  `hero_lead`        VARCHAR(500)     NOT NULL DEFAULT '',
  `hero_image`       VARCHAR(255)     NOT NULL DEFAULT '',
  `facts`            TEXT             NOT NULL,
  `dishes`           TEXT             NOT NULL,
  `faq`              TEXT             NOT NULL,
  `meta_title`       VARCHAR(160)     NOT NULL DEFAULT '',
  `meta_description` VARCHAR(300)     NOT NULL DEFAULT '',
  `sort_order`       INT(11)          NOT NULL DEFAULT 0,
  `status`           TINYINT(1)       NOT NULL DEFAULT 1,
  `updated_at`       DATETIME         NOT NULL,
  PRIMARY KEY (`page_id`),
  UNIQUE KEY `uq_code` (`code`),
  UNIQUE KEY `uq_slug` (`slug`),
  KEY `idx_status_sort` (`status`, `sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `{{PREFIX}}kristal_catering_kit` (
  `kit_id`      INT(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `page_id`     INT(11) UNSIGNED NOT NULL,
  `tier`        VARCHAR(32)      NOT NULL DEFAULT 'standard',
  `name`        VARCHAR(160)     NOT NULL,
  `badge`       VARCHAR(64)      NOT NULL DEFAULT '',
  `subtitle`    VARCHAR(160)     NOT NULL DEFAULT '',
  `price_label` VARCHAR(80)      NOT NULL DEFAULT '',
  `min_guests`  INT(11)          NOT NULL DEFAULT 15,
  `items`       TEXT             NOT NULL,
  `sort_order`  INT(11)          NOT NULL DEFAULT 0,
  `status`      TINYINT(1)       NOT NULL DEFAULT 1,
  PRIMARY KEY (`kit_id`),
  KEY `idx_page_status_sort` (`page_id`, `status`, `sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 1. Чотири сторінки напрямків приготування страв
INSERT INTO `{{PREFIX}}kristal_catering_page`
