VALUES
  (1, 'buffet', 'furshetni-stravy', 'Фуршетні страви',
   'Канапе, брускети, тарталетки, шот-салати та міні-бургери для презентацій, вечірок і корпоративів.',
   'Фуршет · Львів і область',
   'Фуршетні страви на замовлення',
   'Готуємо авторські закуски finger food для корпоративів, презентацій, днів народження та welcome-зон. Привеземо вчасно та подамо на власному фарфоровому або скляному посуді.',
   '',
   '["від 15 гостей","приготування за 24–48 год","подаємо на власному посуді"]',
   '[{"title":"Канапе та закуски на шпажках","desc":"Зручний формат на один укус для вільного спілкування гостей.","items":["Канапе з прошуто, динею та сиром дорблю","Шпажки капрезе з моцарелою і соусом песто","Лосось гравлакс на житньому тості з крем-сиром","Рулетики з баклажана з горіховою пастою"]},{"title":"Брускети та кростіні","desc":"Хрумкий багет із класичними та авторськими начинками.","items":["Брускета з ростбіфом та в’яленими томатами","Брускета з авокадо-мусом та креветкою","Кростіні з паштетом із курячої печінки та ягідним конфітюром","Брускета з хамоном, грушею та брі"]},{"title":"Тарталетки, шоти та міні-бургери","desc":"Ситий акцент фуршетного столу для тривалих подій.","items":["Порційні салати у скляних шотах (Цезар, з тунцем, грецький)","Міні-бургери з яловичою котлетою та карамелізованою цибулею","Кіш лорен порційний із куркою та грибами / шпинатом і фетою","Профітролі з мусом із копченого лосося"]},{"title":"Солодкий фуршет та фрукти","desc":"Легке завершення події без потреби в приборах.","items":["Панна-кота з манго або ягідним кулі в шотах","Тарталетки з заварним кремом і свіжими ягодами","Еклери та профітролі міні-формату","Сезонні фруктові шпажки"]}]',
   '[{"q":"За скільки часу потрібно замовляти фуршетні страви?","a":"Оптимально — за 2–3 дні до події. Для невеликих замовлень можемо підготувати фуршет за 24 години за умови вільного слота кухні."},{"q":"Чи можна замовити страви разом із сервіруванням і посудом?","a":"Так, це наша ключова перевага: ми не лише приготуємо страви, а й привеземо етажерки, тарілки, келихи, коктейльні столи та скатертини з нашого складу у Львові."},{"q":"Як розраховується вартість без фіксованого прайсу?","a":"Оберіть готовий комплекс або залиште заявку з датою й кількістю гостей — менеджер адаптує меню під ваш бюджет і надішле точний кошторис за 15 хвилин."}]',
   'Фуршетні страви у Львові — готові комплекси та меню | Крістал',
   'Приготування фуршетних страв у Львові: канапе, брускети, тарталетки, міні-бургери та готові комплекси з подачею на власному посуді «Крістал».',
   1, 1, NOW()),

  (2, 'banquet', 'banketni-stravy', 'Банкетні страви',
   'Холодні закуски, салати, гарячі основні страви з м’яса й риби та гарніри з подачею в мармітах.',
   'Банкет · Сімейні та ділові події',
   'Банкетні страви для вашої події',
   'Повноцінне банкетне меню для ювілеїв, корпоративних вечорів, хрестин і домашніх свят у Львові. Готуємо ресторанні страви та забезпечуємо повне сервірування столу.',
   '',
   '["від 15 гостей","гарячі страви в чафінгдішах","посуд і текстиль в одному замовленні"]',
   '[{"title":"Холодні закуски та нарізки","desc":"Ефектна подача на порцелянових плато та дерев’яних дошках.","items":["М’ясне плато: буженина, ростбіф, курячий рулет, домашня ковбаса","Сирне плато з медом, горіхами та виноградом","Рибна нарізка: слабосолений лосось, масляна, скумбрія","Овочеве асорті та домашні соління"]},{"title":"Салати банкетні","desc":"Подаємо в загальних салатницях або порційно під формат розсадки.","items":["Салат із печеним буряком, козячим сиром та руколою","Класичний Цезар з куркою або креветками","Теплий салат із телятиною гриль та овочами","Салат із лососем, авокадо та міксом салатів"]},{"title":"Гарячі основні страви та гарніри","desc":"Привозимо в термобоксах і підтримуємо температуру в мармітах.","items":["Стейк зі свинини або медальйони з телятини під вишневим соусом","Запечене філе лосося з лимонно-вершковим соусом","Куряче філе су-від із травами або качина ніжка конфі","Картопля по-селянськи з розмарином, овочі гриль, вершкове пюре"]},{"title":"Перші страви та доповнення","desc":"Для традиційних застіль та багатоетапних банкетів.","items":["Бульйон із домашньою локшиною або бограч у казані","Свіжоспечений хліб та пампушки з часником","Авторські соуси до м’яса та риби"]}]',
   '[{"q":"Як гарячі банкетні страви залишаються теплими при доставці?","a":"Ми доставляємо гарячі позиції у професійних термобоксах і, за потреби, встановлюємо марміти (чафінгдіші) на пальниках для підтримання температури протягом усього вечора."},{"q":"Чи потрібно окремо шукати офіціантів і посуд?","a":"Ні, у «Крістал» можна замовити і страви, і повний комплект банкетного посуду, келихів, скатертин, меблів та обслуговування персоналом."},{"q":"Чи можна змінювати страви у готовому комплексі?","a":"Так, усі комплекси гнучкі: ми без проблем замінимо позиції з урахуванням побажань гостей (дитяче, вегетаріанське або безглютенове меню)."}]',
   'Банкетні страви у Львові — виїзні банкети та комплекси меню | Крістал',
   'Замовити банкетні страви у Львові: холодні закуски, салати, гарячі страви, гарніри. Готові банкетні комплекси разом із посудом та мармітами від «Крістал».',
   2, 1, NOW()),

  (3, 'coffeebreak', 'kava-breik', 'Кава-брейк',
